// Store Data Function - Improved Version
const topic = msg.topic;
const value = msg.payload;

switch (topic) {
    case 'child_name':
        flow.set('child_name', value);
        node.status({fill:'blue', shape:'dot', text:'Name saved'});
        break;

    case 'exercise':
        flow.set('exercise', value);
        break;

    case 'phase':
        flow.set('phase', value);
        break;

    case 'max_weight':
        flow.set('max_weight', value);
        break;

    default:
        node.warn(`Unknown topic: ${topic}`);
}

return msg;

// Get values from flow
let child = flow.get('child_name') || '';
let exercise = flow.get('exercise') || 'walk';
let phase = flow.get('phase') || '1';
let weight = flow.get('max_weight') || 30;

// Check if child name is entered
if (child.trim() === '') {
    node.status({ fill: 'red', shape: 'ring', text: '⚠️ Enter child name first' });
    return null; // Stop execution, do not send message
}

// Prepare message for ESP32
msg.payload = {
    action: "start",
    exercise: exercise,
    phase: phase,
    max_weight: parseFloat(weight)
};
msg.topic = "BushraIzzaHafsa/robot/control/start";

// Update node status
node.status({fill:'green', shape:'dot', text:'🎯 Start command sent'});
flow.set("system_status", "active");
flow.set("action", "start");

return msg;

let status = msg.payload.status;

let data = {
    child_name: flow.get('child_name') || '',
    exercise: flow.get('exercise') || 'walk',
    phase: flow.get('phase') || '1',
    max_weight: flow.get('max_weight') || 30,
    systemStatus: status === "started" ? "active" : "inactive"
};

msg.payload = data;

if (status === "started") {
    node.status({fill:'blue', shape:'dot', text:'Session Active Logged'});
} else {
    node.status({fill:'red', shape:'ring', text:'Session Inactive Logged'});
}

return msg;

// تحديث حالة النظام و نوع الإجراء
flow.set("system_status", "inactive");
flow.set("action", "stop");

// تجهيز البيانات للـ Google Sheet كـ object
let data = {
    child_name: flow.get('child_name') || '',
    exercise: flow.get('exercise') || 'walk',
    phase: flow.get('phase') || '1',
    max_weight: flow.get('max_weight') || 30,
    systemStatus: "inactive"
};

msg.payload = data;

// topic للـ MQTT
msg.topic = "BushraIzzaHafsa/robot/control/stop";

// تحديث حالة النود على الـ Dashboard
node.status({fill:'red', shape:'ring', text:'Session stopped'});

return msg;

// تحديث حالة النظام و نوع الإجراء
flow.set("system_status", "inactive");
flow.set("action", "emergency_stop");

// تجهيز البيانات للـ Google Sheet كـ object
let data = {
    child_name: flow.get('child_name') || '',
    exercise: flow.get('exercise') || 'walk',
    phase: flow.get('phase') || '1',
    max_weight: flow.get('max_weight') || 30,
    systemStatus: "inactive"
};
msg.payload = data;

// topic للـ MQTT
msg.topic = "BushraIzzaHafsa/robot/control/emergency_stop";

// تحديث حالة النود على الـ Dashboard
node.status({fill:'orange', shape:'ring', text:'Emergency stopped'});

return msg;

// Read data from payload
let currentWeight = msg.payload.currentWeight;
let maxWeight = msg.payload.maxWeight;
let systemStatus = msg.payload.systemStatus || 'inactive';

// Get previous alerts
let alerts = global.get('alerts') || [];

let alertMsg = '';
let alertType = 'info';

if(systemStatus.toLowerCase() === 'active'){
    if(currentWeight > maxWeight){
        alertMsg = `⚠️ Current weight (${currentWeight} kg) exceeded maximum (${maxWeight} kg)`;
        alertType = 'danger';
    } else {
        alertMsg = `✅ Weight is normal (${currentWeight} kg)`;
        alertType = 'success';
    }
} else {
    alertMsg = 'ℹ️ System is inactive';
    alertType = 'info';
}

// Add new alert on top
alerts.unshift({ message: alertMsg, type: alertType, timestamp: Date.now() });

// Save to global context
global.set('alerts', alerts);

msg.payload = alerts;
return msg;

// Get data from the script
let data = msg.payload;

// ========== For diagnostics ==========
// Log the data type in Node-RED log
node.log("========== Starting data processing ==========");
node.log("Data type: " + typeof data);
node.log("Is it an array? " + Array.isArray(data));
if (data) {
    node.log("Number of elements: " + (Array.isArray(data) ? data.length : 'Not an array'));
    if (Array.isArray(data) && data.length > 0) {
        node.log("First element type: " + typeof data[0]);
        node.log("Is first element an object? " + (typeof data[0] === 'object'));
        node.log("First element keys: " + Object.keys(data[0]).join(', '));
    }
}
// ==============================

// Ensure data exists
if (!data) {
    node.log("❌ No data available!");
    msg.payload = [];
    return msg;
}

// If data is an array of objects (as the script currently sends)
if (Array.isArray(data)) {
    if (data.length === 0) {
        node.log("✅ Empty array");
        msg.payload = [];
        return msg;
    }

    // Verify that elements are objects
    if (typeof data[0] === 'object' && !Array.isArray(data[0])) {
        node.log("✅ Data is correct: array of objects");
        node.log("✅ Number of records: " + data.length);
        // Data is ready for display as is
        msg.payload = data;
        return msg;
    }

    // If it's an array of arrays (for compatibility)
    if (Array.isArray(data[0])) {
        node.log("🔄 Converting array of arrays to objects");
        let list = [];
        data.forEach(row => {
            if (row.length >= 5) {
                list.push({
                    child_id: row[0],
                    full_name: row[1],
                    first_seen: row[2],
                    session_count: row[3],
                    System_Status: row[4]
                });
            }
        });
        node.log("✅ Converted " + list.length + " records");
        msg.payload = list;
        return msg;
    }
}

// If data is an object and not an array (e.g., {data: [...]})
if (typeof data === 'object' && !Array.isArray(data)) {
    node.log("🔍 Data is an object, looking for an array inside it");

    // Look for any property containing an array
    for (let key in data) {
        if (Array.isArray(data[key])) {
            node.log("✅ Found array in property: " + key);
            msg.payload = data[key];
            return msg;
        }
    }
}

// If we reached here, the format is unknown
node.log("❌ Unknown data format: " + JSON.stringify(data).substring(0, 200));
msg.payload = [];
return msg;

const data = msg.payload;

// ===== 1. Save Joint Angles =====
let jointsArray = [90,90,90,90,90,90];

if (data.joint_angles) {
    jointsArray = [
        Number(data.joint_angles.Left_Hip) || 10,
        Number(data.joint_angles.Left_Knee) || 90,
        Number(data.joint_angles.Left_Ankle) || 90,
        Number(data.joint_angles.Right_Hip) || 90,
        Number(data.joint_angles.Right_Knee) || 90,
        Number(data.joint_angles.Right_Ankle) || 90
    ];

    // تشخيص
    node.warn("✅ Joint Angles: " + jointsArray.map(a => a.toFixed(1)).join(', '));
}

// ===== 2. Current Weight
let weightMsg = {
    payload: Number(data.currentWeight) || 0
};

// ===== 3. Muscle Strength
let muscleMsg = {
    payload: Number(data.muscleStrength) || 0
};

// ===== 4. Send Joint Angles to UI (مصفوفة مباشرة)
let jointMsg = {
    payload: jointsArray,
    topic: "joint_angles"
};

// ===== 5. Google Sheet
let sheetMsg = {
    payload: {
        currentWeight: Number(data.currentWeight) || 0,
        muscleStrength: Number(data.muscleStrength) || 0,
        childName: data.childName || "",
        exerciseType: data.exerciseType || "",
        phase: data.phase || "",
        maxWeight: data.maxWeight || 0,
        systemStatus: data.systemStatus || "inactive"
    }
};

return [weightMsg, muscleMsg, jointMsg, sheetMsg];

let text = msg.payload.text;

if (!text) {
    text = "You are awesome 👏";
}

// audio URL
msg.url = "https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=" + encodeURIComponent(text);

msg.method = "GET";

// important
msg.headers = {
    "User-Agent": "Mozilla/5.0"
};

return msg;

if (!msg.payload || msg.payload.length < 100) {
    node.error("❌ Audio is empty or failed to download");
    return null;
}

node.warn("✅ Audio downloaded");
return msg;

// Convert  response to JSON
let colabResponse = {};
try { 
    colabResponse = JSON.parse(msg.payload); 
    node.warn('✅ Successfully converted Colab response'); 
    node.warn(`📊 Movement: ${colabResponse.movement || 'undefined'}, Percentage: ${colabResponse.percentage || 0}%`);
} catch(e){ 
    node.warn('⚠️ Response is not JSON, using default data');
    colabResponse = msg.payload;
}

// Prepare prompt
let movementText = colabResponse.movement === 'moving' ? 'very active' : 'still';
let percentage = colabResponse.percentage || 0;
let feedback = colabResponse.feedback || 'Good movement';

let promptText = `You are an enthusiastic and warm physiotherapy coach working with a ${3}-${4} year old child right in front of you.

You can see the child moving and here is exactly what you observe:
- The child is ${movementText} right now
- Movement level: ${colabResponse.message || 'Unknown'}
- Activity percentage: ${percentage}%
- The most moving body part you see: ${colabResponse.most_active || 'Unknown'}
- How their body looks: ${colabResponse.posture || 'Unknown'}

Speak DIRECTLY to the child as if you are looking at them right now.
Use very simple words a 3-4 year old understands.
Be warm, excited and loving like a fun coach playing with them.

Rules:
- If percentage is 0 or no movement: gently encourage them to start moving
- If percentage is 1-40%: cheer them to move more
- If percentage is 41-100%: celebrate their amazing effort loudly

Requirement: One short sentence spoken directly to the child (max 20 words). No emojis. Plain text only.`;
node.warn(`📝 Sending prompt to OpenRouter...`);

// OpenRouter format
msg.payload = {
    model: "meta-llama/llama-3-8b-instruct",
    messages: [
        {role: "system", content: "You are a kids sports coach, use motivational and encouraging style."},
        {role: "user", content: promptText}
    ]
};

msg.headers = {
    "Authorization": "Bearer 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",
    "Content-Type": "application/json"
};

msg.method = "POST";
msg.url = "https://openrouter.ai/api/v1/chat/completions";

return msg;

let aiText = '';

// If there is an error
if (msg.payload && msg.payload.error) {
    node.warn("❌ OpenRouter has an issue - using fallback");
    aiText = 'No text - fallback';
}

// Extract text - OpenRouter/OpenAI format
else if (msg.payload?.choices?.[0]?.message?.content) {
    aiText = msg.payload.choices[0].message.content;
    aiText = aiText.replace(/[\*\#\_\n]/g, ' ').trim();
    node.warn("✅ Text extracted");
}

// fallback
else {
    node.warn("⚠️ No text - fallback");
    aiText = 'Great! Keep going champ 👏';
}

// Save text
msg.payload = {
    text: aiText
};

return msg;

msg.payload = JSON.stringify({
    movement: msg.payload.movement,
    percentage: msg.payload.percentage,
    posture: msg.payload.posture,
    most_active: msg.payload.most_active,
    level: msg.payload.level,
    angles: msg.payload.angles,
    feedback: msg.payload.feedback
});

return msg;
